<div class="grid grid-cols-2 gap-4"><?php if ($editing && !$warehouseInput): ?><label class="field"><span>Code</span><input class="input" name="code" value="<?= pl_e((string)$editing['code']) ?>" readonly></label><?php else: ?><?php pl_starter_field('Code','code',$values['code']??''); ?><?php endif; pl_starter_field('Name','name',$values['name']??''); pl_starter_field('Reason','reason',$warehouseInput['reason']??''); ?></div>
