<form method="post" action="<?= pl_e(pl_url('/inventory',$filters)) ?>" class="flex flex-col gap-3"><h3 class="section-title">Transfer stock between locations</h3><?php pl_ui_return_filters($filters); pl_starter_form($company,'transfer',['request_key'=>$transferInput['request_key']??null]); ?>
<div class="grid grid-cols-2 gap-4"><?php pl_starter_select('From','from_warehouse_id',$warehouseOptions,$transferInput['from_warehouse_id']??($warehouse_filter??'')); pl_starter_select('To','to_warehouse_id',$warehouseOptions,$transferInput['to_warehouse_id']??''); pl_starter_select('Stock product','product_id',pl_starter_options($stockProducts),$transferInput['product_id']??''); pl_starter_field('Quantity in base units','quantity',$transferInput['quantity']??''); pl_starter_field('Date','date',$transferInput['date']??gmdate('Y-m-d'),'date'); pl_starter_field('Source reference','reference',$transferInput['reference']??''); pl_starter_field('Reason','reason',$transferInput['reason']??''); ?></div>
<p class="text-xs text-ink-muted">An insufficient quantity in the source location is rejected and your entries are retained.</p><button class="btn btn-secondary">Record transfer</button></form>
